package com.game_manager.gm.report;
import com.game_manager.gm.document.DocumentService; import com.game_manager.gm.report.dto.*; import jakarta.validation.Valid; import java.util.*; import org.springframework.core.io.InputStreamResource; import org.springframework.http.*; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/reports") public class ReportController {private final ReportService reports;private final DocumentService documents;public ReportController(ReportService r,DocumentService d){reports=r;documents=d;}
 @GetMapping("/definitions") public List<ReportDefinitionResponse> definitions(){return reports.definitions();}@PostMapping public ResponseEntity<ReportResponse> generate(@Valid @RequestBody GenerateReportRequest r){return ResponseEntity.status(HttpStatus.ACCEPTED).body(reports.generate(r));}@GetMapping public List<ReportResponse> list(){return reports.list();}@GetMapping("/{id}") public ReportResponse get(@PathVariable UUID id){return reports.get(id);}@PostMapping("/{id}/cancel") public ReportResponse cancel(@PathVariable UUID id){return reports.cancel(id);}
 @GetMapping("/{id}/download") public ResponseEntity<InputStreamResource> download(@PathVariable UUID id){UUID documentId=reports.downloadDocument(id);DocumentService.Download d=documents.download(documentId,null,false);return ResponseEntity.ok().header(HttpHeaders.CONTENT_DISPOSITION,ContentDisposition.attachment().filename(d.filename(),java.nio.charset.StandardCharsets.UTF_8).build().toString()).header(HttpHeaders.CACHE_CONTROL,"private, no-store").header("X-Content-Type-Options","nosniff").contentType(MediaType.parseMediaType(d.contentType())).contentLength(d.size()).body(new InputStreamResource(d.stream()));}
 @GetMapping("/schedules") public List<ScheduleResponse> schedules(){return reports.schedules();}@PostMapping("/schedules") public ResponseEntity<ScheduleResponse> createSchedule(@Valid @RequestBody ScheduleRequest r){return ResponseEntity.status(HttpStatus.CREATED).body(reports.createSchedule(r));}@PutMapping("/schedules/{id}") public ScheduleResponse updateSchedule(@PathVariable UUID id,@RequestParam long version,@Valid @RequestBody ScheduleRequest r){return reports.updateSchedule(id,version,r);}@DeleteMapping("/schedules/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) public void deleteSchedule(@PathVariable UUID id){reports.deleteSchedule(id);}
 @GetMapping("/templates") public List<TemplateResponse> templates(){return reports.templates();}@PostMapping("/templates") public ResponseEntity<TemplateResponse> createTemplate(@Valid @RequestBody TemplateRequest r){return ResponseEntity.status(HttpStatus.CREATED).body(reports.createTemplate(r));}@DeleteMapping("/templates/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) public void deleteTemplate(@PathVariable UUID id){reports.deleteTemplate(id);}}
